"""Ground-truth Manim API reference, generated by introspecting the actually
installed `manim` package rather than relying on hand-written/memorized
documentation.

Why this exists: scene_coder.py's prompt used to tell the model that Code's
rendered lines live on a `.code` attribute -- that was simply wrong for the
installed Manim version (the real attribute is `.code_lines`), and it crashed
two real scenes before anyone caught it. A hand-written "here's the Manim API"
reference file has the exact same failure mode: whoever writes it is going
from memory, and memory drifts from whatever version is actually installed.
Introspecting the live package instead means this text is always accurate for
the Manim version actually running, on whatever machine it runs on, and it
doesn't need to be maintained by hand or kept in sync after a Manim upgrade.

Computed once at import time (not per-call) and spliced into scene_coder's
SYSTEM_PROMPT, so every generation call is grounded in the real API instead of
the model's (or a prompt author's) memory of it.
"""

import inspect

from manim import Code, Mobject, SurroundingRectangle, Table

_POSITIONING_METHODS = [
    "move_to", "shift", "next_to", "to_edge", "to_corner",
    "scale", "scale_to_fit_width", "scale_to_fit_height",
]
_TABLE_METHODS = ["get_rows", "get_columns", "get_entries", "get_entries_without_labels"]


def _signature_line(cls, name: str) -> str:
    method = getattr(cls, name, None)
    if method is None:
        return None
    try:
        sig = inspect.signature(method)
    except (TypeError, ValueError):
        return f"  {cls.__name__}.{name}(...)"
    return f"  {cls.__name__}.{name}{sig}"


def _build_reference() -> str:
    code_sample = Code(
        code_string="x = 1", language="python", formatter_style="monokai",
        background="window", add_line_numbers=True,
    )
    code_attrs = [
        f"  Code.code_lines: {type(code_sample.code_lines).__name__} "
        "-- indexable by line number, code_lines[0] is the first source line "
        "(there is no .code or .chars attribute)"
    ]

    lines = [
        "Ground-truth Manim API notes -- introspected from the installed manim "
        "package, not memorized, so trust this over general Manim knowledge if "
        "they ever disagree:",
        "",
        "Code mobject:",
        *code_attrs,
        "",
        "Mobject positioning methods (all take a single point/mobject/vector "
        "argument or explicit kwargs -- never separate x, y, z positional args):",
        *filter(None, (_signature_line(Mobject, name) for name in _POSITIONING_METHODS)),
        "",
        "Table:",
        *filter(None, (_signature_line(Table, name) for name in _TABLE_METHODS)),
        "",
        "SurroundingRectangle:",
        _signature_line(SurroundingRectangle, "__init__"),
    ]
    return "\n".join(lines)


MANIM_API_REFERENCE = _build_reference()
